using System;
using System.Linq;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using System.IO;
namespace Dafeiyu.Tests {
 public static class ProactiveConversationTests {
  sealed class Api:IConversationApi {public IList<ChatMessage> Seen;public Task<string> ChatAsync(ConnectionSettings s,IList<ChatMessage> m,CancellationToken c){Seen=m.Select(x=>x.Copy()).ToList();return Task.FromResult("answer");}public Task<string> TranscribeAsync(ConnectionSettings s,byte[] b,CancellationToken c){return Task.FromResult("");}public Task<byte[]> SpeechAsync(ConnectionSettings s,string v,string t,CancellationToken c){return Task.FromResult(new byte[0]);}public void Dispose(){}}
  sealed class Speech:IReplySpeech {public Task SpeakAsync(string t,PetSettings s,CancellationToken c){return Task.FromResult(0);}public void SetVolume(int v){}public void Stop(){}public void Dispose(){}}
  static void Check(bool value,string message){if(!value)throw new Exception(message);}
  public static int Main(){try{
   var log=new ConversationLog();var first=log.RegisterProactive("event1","hello");
   Check(log.RegisterProactive("event1","changed").Id==first.Id && log.Messages.Count==1 && log.Messages[0].Content=="hello","registration must be idempotent and immutable");
   log.Update(first.Id,"overwritten","complete");Check(log.Messages[0].Content=="hello","proactive statement is immutable");
   var request=log.ForRequest("","reply");Check(request.Count==3 && request[0].Role=="user" && request[1].Content=="hello" && request[2].Content=="reply","request projects proactive statement with protocol context");
   bool rejected=false;try{log.ForRegeneration(first.Id,"");}catch(InvalidOperationException){rejected=true;}Check(rejected,"initial proactive message must not regenerate");
   log.Commit("reply","answer");request=log.ForRegeneration(log.Messages.Last().Id,"");Check(request.Any(m=>m.Content=="hello") && request.Last().Content=="reply","regeneration keeps proactive context");
   var restored=new ConversationLog();restored.Replace(log.Messages);request=restored.ForRequest("","next");Check(restored.Messages.Count==3 && request.Any(m=>m.Content=="hello") && request.Count==5,"restored history projects proactive context without persisting synthetic user");ChatMessage pendingUser;var pending=restored.BeginTurn("unfinished","text",out pendingUser);restored.Update(pending.Id,"partial","cancelled");Check(restored.ForRequest("","next").All(m=>m.Content!="unfinished" && m.Content!="partial"),"incomplete ordinary turns stay excluded");
   var budgetMessages=new List<object>();budgetMessages.Add(new Dictionary<string,object>{{"role","user"},{"content","Context: the assistant previously initiated the following conversation."}});budgetMessages.Add(new Dictionary<string,object>{{"role","assistant"},{"content","hello"}});budgetMessages.Add(new Dictionary<string,object>{{"role","user"},{"content",new string('x',10000)}});budgetMessages.Add(new Dictionary<string,object>{{"role","assistant"},{"content",new string('y',10000)}});budgetMessages.Add(new Dictionary<string,object>{{"role","user"},{"content","next"}});var budget=AgentWorkspace.ForContextBudget(2048);budget.BeginTask(new AgentTaskState{Workspace=budget.Root,Goal="next"});AgentContextBudget.PrepareAsync(budgetMessages,false,budget,(prior,ct)=>Task.FromResult("summary"),CancellationToken.None,null,0,true).GetAwaiter().GetResult();Check(budgetMessages.Cast<Dictionary<string,object>>().Any(m=>(string)m["role"]=="assistant" && (string)m["content"]=="hello"),"compaction retains original proactive statement");
   Check((string)((Dictionary<string,object>)budgetMessages[1])["content"]=="hello","compaction preserves projected pair order");
   var now=new DateTime(2026,1,1,0,0,0,DateTimeKind.Utc);var store=new ProactiveEventStore(()=>now);var item=new ProactiveEvent("event1","pet","hello",new byte[]{137,80,78,71,0,0,0,0},now,"window",null);Check(store.Register(item)=="event1" && store.Register(item)=="event1","stable registration");Check(store.BindConversation("event1","pet","conversation")=="conversation" && store.BindConversation("event1","pet","other")=="conversation","binding is idempotent");rejected=false;try{store.BindConversation("event1","other","conversation");}catch(InvalidOperationException){rejected=true;}Check(rejected,"wrong pet must be rejected");now=now.AddMinutes(16);Check(store.TryGet("event1").Png==null && store.TryGet("event1").Text=="hello","expired image is dropped while text remains");
   var session=new ConversationSession(new Api(),new Speech(),()=>null);session.SelectPersona("pet");var attached=session.AttachProactive(item);Check(session.AttachProactive(item).Id==attached.Id && session.History.Messages.Count==1,"session attaches once");session.SelectPersona("other");rejected=false;try{session.AttachProactive(item);}catch(InvalidOperationException){rejected=true;}Check(rejected,"session rejects another companion's event");session.Dispose();store.Dispose();
   now=DateTime.UtcNow;var bounded=new ProactiveEventStore(()=>now);var bytes=new byte[2*1024*1024];bytes[0]=137;bytes[1]=80;bytes[2]=78;bytes[3]=71;for(int i=0;i<3;i++)bounded.Register(new ProactiveEvent("e"+i,"pet","text",bytes,now.AddSeconds(i-3),"window",null,"summary"));Check(bounded.TryGet("e0").Png==null && bounded.TryGet("e1").Png.Length==bytes.Length && bounded.TryGet("e2").Png.Length==bytes.Length,"only two images and four MiB retained");bounded.ClearImages();Check(bounded.TryGet("e2").Png==null && bounded.TryGet("e2").Description==null,"clear removes images and descriptions");bounded.Dispose();
   var api=new Api();using(var active=new ConversationSession(api,new Speech(),()=>null)){active.SelectPersona("pet");active.AttachProactive(new ProactiveEvent("live","pet","visible",new byte[]{137,80,78,71,0,0,0,0},DateTime.UtcNow,"window",null,"private observation"));var settings=new PetSettings{AgentEnabled=false,ReadReplies=false,Text=new ConnectionSettings{BaseUrl="http://127.0.0.1:9001/v1",Model="chat",ImageSupport=CapabilitySupport.Supported}};active.SendTextAsync("reply",settings,"pet").GetAwaiter().GetResult();Check(api.Seen.Any(m=>m.Attachments!=null&&m.Attachments.Any(a=>a.IsImage)) && api.Seen.Any(m=>m.Content=="visible") && api.Seen.Any(m=>m.Content.Contains("private observation")),"plain reply receives original image and statement");Check(active.History.Messages.All(m=>(m.Attachments==null||m.Attachments.Count==0) && !m.Content.Contains("private observation")),"automatic context never enters history");settings.AgentEnabled=true;active.SendTextAsync("work",settings,"pet").GetAwaiter().GetResult();Check(api.Seen.All(m=>(m.Attachments==null||m.Attachments.Count==0) && !m.Content.Contains("private observation")) && api.Seen.Any(m=>m.Content=="visible"),"work mode receives text without automatic image or description");}
   api=new Api();using(var active=new ConversationSession(api,new Speech(),()=>null)){active.SelectPersona("pet");active.AttachProactive(new ProactiveEvent("old","pet","original",new byte[]{137,80,78,71,0,0,0,0},DateTime.UtcNow,"window",null,"saved description"));var settings=new PetSettings{AgentEnabled=false,ReadReplies=false,Text=new ConnectionSettings{BaseUrl="http://127.0.0.1:9001/v1",Model="chat",ImageSupport=CapabilitySupport.Unsupported}};active.SendTextAsync("text reply",settings,"pet").GetAwaiter().GetResult();Check(api.Seen.Any(m=>m.Content.Contains("saved description")) && api.Seen.All(m=>m.Attachments==null||m.Attachments.Count==0),"nonvisual model reuses description without image routing");active.ProactiveEvents.ClearImages();active.SendTextAsync("after clear",settings,"pet").GetAwaiter().GetResult();Check(api.Seen.Any(m=>m.Content=="original") && api.Seen.All(m=>!m.Content.Contains("saved description")),"cleared context falls back to original text");bool failed=false;try{active.SendTextAsync("manual",settings,"pet",attachments:new[]{ChatAttachment.CreateImage("manual.png",new byte[]{137,80,78,71,0,0,0,0})}).GetAwaiter().GetResult();}catch(ApiException){failed=true;}Check(failed,"manual image still enforces routing");}
   var shared=new ProactiveEventStore();var firstSession=new ConversationSession(new Api(),new Speech(),()=>null);var secondSession=new ConversationSession(new Api(),new Speech(),()=>null);firstSession.ProactiveEvents=shared;secondSession.ProactiveEvents=shared;firstSession.SelectPersona("pet1");secondSession.SelectPersona("pet2");firstSession.AttachProactive(new ProactiveEvent("shared1","pet1","a",new byte[]{137,80,78,71,0,0,0,0},DateTime.UtcNow,"a",null));secondSession.AttachProactive(new ProactiveEvent("shared2","pet2","b",new byte[]{137,80,78,71,0,0,0,0},DateTime.UtcNow,"b",null));firstSession.Clear();firstSession.Dispose();Check(shared.TryGet("shared2").Png!=null,"closing one session preserves another companion's shared context");secondSession.Dispose();shared.Dispose();
   var directory=Path.Combine(Path.GetTempPath(),"proactive-history-"+Guid.NewGuid().ToString("N"));var history=new HistoryStore(directory);var api2=new Api();using(var active=new ConversationSession(api2,new Speech(),()=>null,history)){active.SelectPersona("pet");active.AttachProactive(new ProactiveEvent("persist","pet","saved original",new byte[]{137,80,78,71,0,0,0,0},DateTime.UtcNow,"window",null,"private observation"));Check(!Directory.Exists(directory)||Directory.GetFiles(directory).Length==0,"attachment alone does not persist history");var settings=new PetSettings{AgentEnabled=false,ReadReplies=false,Text=new ConnectionSettings{BaseUrl="http://127.0.0.1:9001/v1",Model="chat",ImageSupport=CapabilitySupport.Supported}};active.SendTextAsync("reply",settings,"pet").GetAwaiter().GetResult();active.FlushHistoryAsync().GetAwaiter().GetResult();Check(!active.ExportHistory().Contains("private observation"),"export excludes transient observation");}using(var fresh=new ConversationSession(new Api(),new Speech(),()=>null,new HistoryStore(directory))){fresh.SelectPersona("pet");Check(fresh.History.Messages.Count==3 && fresh.History.ForRequest("","next").Any(m=>m.Content=="saved original") && fresh.History.Messages.All(m=>!m.Content.Contains("private observation")&&(m.Attachments==null||m.Attachments.Count==0)),"encrypted restart preserves only genuine text and restores projection");}
   Console.WriteLine("Proactive conversation tests passed");return 0;
  }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 }
}
